<?php
$sfRoot=base_url('store/'.$settings->store_slug);$sfUrl=$sfRoot.'/product/'.(int)$product->id;$sfService=($product->product_type??'physical')==='service'||!empty($product->service_bit);$sfQuote=!empty($product->requires_quote);$sfPhysical=($product->product_type??'physical')==='physical'&&!$sfService;
$sfPayload=['id'=>(int)$product->id,'type'=>$product->product_type??'physical','name'=>$product->item_name,'price'=>(float)$product->effective_price,'image'=>$product->item_image??'','stock'=>(float)$product->stock];$sfWa=preg_replace('/[^0-9]/','',$settings->whatsapp_number??'');
?>
<section class="sf-product-experience" data-sf-product-experience data-conversion="<?= !$sfService&&!$sfQuote?'1':'0'; ?>" data-product="<?= htmlspecialchars(json_encode($sfPayload,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT),ENT_QUOTES); ?>" data-variant="<?= ($product->item_group??'')==='Variants'?'1':'0'; ?>" data-checkout="<?= $sfRoot.'/checkout'; ?>" data-url="<?= htmlspecialchars($sfUrl,ENT_QUOTES); ?>" data-whatsapp="<?= $sfWa; ?>" data-backorder="<?= !empty($settings->allow_backorder)?'1':'0'; ?>">
<?php if(!$sfService&&!$sfQuote): ?><div class="sf-product-actions"><?php if(!empty($cart_enabled)&&($product_checkout_supported??true)&&!empty($site_content['buy_now'])): ?><button type="button" class="sf-feature-button primary" data-sf-buy-now>Buy now ↗</button><?php endif; ?><?php if(!empty($site_content['whatsapp_order'])&&!empty($settings->allow_whatsapp)&&$sfWa): ?><button type="button" class="sf-feature-button whatsapp" data-sf-order-whatsapp>Order via WhatsApp ↗</button><?php endif; ?></div><?php endif; ?>
<?php if($sfPhysical&&!empty($site_content['pickup_enabled'])): ?><details class="sf-pickup"><summary>Pickup & store information</summary><?php if($site_content['pickup_ready_text']): ?><p><?= htmlspecialchars($site_content['pickup_ready_text']); ?></p><?php endif; ?><p>Confirm stock and your preferred collection time with the team.</p><?php if($public_branches): ?><?php foreach($public_branches as $branch): ?><article><strong><?= htmlspecialchars($branch->warehouse_name); ?></strong><address><?= htmlspecialchars(trim(($branch->address??'')."\n".($branch->city??''))); ?></address><?php if(!empty($branch->mobile)): ?><a href="tel:<?= preg_replace('/[^+0-9]/','',$branch->mobile); ?>"><?= htmlspecialchars($branch->mobile); ?></a><?php endif; ?></article><?php endforeach; ?><?php else: ?><strong><?= htmlspecialchars($store->store_name??'Our store'); ?></strong><address><?= htmlspecialchars($settings->store_address??''); ?></address><?php endif; ?></details><?php endif; ?>
<?php if(!empty($site_content['contact_enabled'])): ?><p><a href="<?= $sfRoot.'/contact?product_id='.(int)$product->id.'#contact-form'; ?>">Ask a question about this <?= $sfService?'service':'product'; ?> ↗</a></p><?php endif; ?>
<?php if(!empty($site_content['product_sharing'])): ?><div class="sf-share" aria-label="Share this product"><span>Share</span><a href="https://www.facebook.com/sharer/sharer.php?u=<?= rawurlencode($sfUrl); ?>" target="_blank" rel="noopener noreferrer">Facebook</a><a href="https://twitter.com/intent/tweet?url=<?= rawurlencode($sfUrl); ?>&text=<?= rawurlencode($product->item_name); ?>" target="_blank" rel="noopener noreferrer">X</a><a href="https://pinterest.com/pin/create/button/?url=<?= rawurlencode($sfUrl); ?>&media=<?= rawurlencode(mp_storefront_image_url($product->item_image??'')); ?>&description=<?= rawurlencode($product->item_name); ?>" target="_blank" rel="noopener noreferrer">Pinterest</a><button type="button" data-sf-copy-link>Copy link</button></div><?php endif; ?><p class="sf-product-status" data-sf-product-status role="status"></p></section>
<script defer src="<?= base_url('theme/js/storefront_features.js?v=2'); ?>"></script>
